//Exact zero-strength420200 allocation followed by three actual420be0 callbacks.
//CRTmemcpy/audio/effect-render emission are boundaries; UNIT query/damage real.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZRound37ZeroBlastFlashOracleV2 extends GhidraScript{static final long RET=0x12345000L,S=0x7fff0000L,U=0x5e30c8L,O=0x612f80L,B=0x5c5e38L,BL=0x595b12L,W=0x1800000L,Q=W+4096;int fx,audio;long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void run(EmulatorHelper e,long entry)throws Exception{e.writeRegister("ESP",S);put(e,S,4,RET);if(entry==0x420200){put(e,S+4,4,500);put(e,S+8,4,0);e.writeRegister("ECX",0);e.writeRegister("EDX",500);}if(!e.run(toAddr(entry),null,monitor))throw new Exception(e.getLastError());int n=0;while(e.readRegister("EIP").longValue()!=RET){if(++n>40)throw new Exception("loop");long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x47326a){long dest=read(e,sp+4,4),src=read(e,sp+8,4);e.writeMemory(toAddr(dest),e.readMemory(toAddr(src),(int)read(e,sp+12,4)));e.writeRegister("EAX",dest);}else if(pc==0x46e6d0){audio++;}else if(pc==0x402160){fx++;}else throw new Exception("unexpected "+Long.toHexString(pc));long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<32;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{fx=0;audio=0;e.writeMemory(toAddr(U),new byte[240*192]);e.writeMemory(toAddr(W),new byte[0x10000]);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);e.writeMemory(toAddr(0x586aaa),new byte[16384]);byte[]classes=new byte[480];java.util.Arrays.fill(classes,(byte)255);e.writeMemory(toAddr(0x5b65e2),classes);for(int j=0;j<16;j++)put(e,0x5b67e2+j*2,2,32+j);e.writeMemory(toAddr(O),new byte[200*44]);for(int i=0;i<200;i++)put(e,O+i*44,2,-1);e.writeMemory(toAddr(B),new byte[35*88]);for(int i=0;i<35;i++)put(e,B+i*88+4,1,255);e.writeMemory(toAddr(BL),new byte[500]);for(int i=0;i<50;i++)put(e,BL+i*10,2,-1);e.writeMemory(toAddr(0x5b00ce),new byte[500]);for(int i=0;i<50;i++)put(e,0x5b00ce+i*10,2,-1);put(e,0x622d54,4,0x0bb80bb8);put(e,0x622d58,4,0x0c800c80);put(e,0x622d50,2,2048);put(e,0x622d52,2,2048);put(e,0x622cb8,4,0);put(e,0x498c24,2,640);put(e,0x498c20,2,480);put(e,0x4a6e72,1,1);put(e,0x4a6e73,1,0);put(e,0x4a6e76,1,0);put(e,0x4a6f42,1,0);put(e,0x4a6f3a,1,0);put(e,0x4a6f4f,1,0);put(e,0x4d18ee,1,1);put(e,0x4a6e6f,1,0);put(e,0x622dc0,1,0);put(e,0x622dc4,1,0);put(e,0x6323a5,1,0);put(e,0x62b3a4,4,Q);put(e,0x62d5d8,4,Q+4096);e.writeMemory(toAddr(0x635b78),new byte[256+256*32]);put(e,0x635b78+67,1,1);put(e,0x635c78+67*32,1,0);put(e,U+44,2,500);put(e,U+46,2,520);put(e,U+0x7c,1,s%4);put(e,U+0x31,1,4+s/4%4);put(e,U+0x64,1,16+s/4%4);put(e,U+0x98,1,1);put(e,U+0x3a,1,30);put(e,U+0x9c,1,s/16%2==0?0:0x14);put(e,U+0x35,1,1);put(e,U+8,4,s%4==1||s%4==2?W:0);put(e,W+8,2,100);put(e,W+10,2,100);
 for(long pc:new long[]{RET,0x47326a,0x46e6d0,0x402160})e.setBreakpoint(toAddr(pc));run(e,0x420200);for(int tick=0;tick<4;tick++){out.println("{\"scenario\":"+s+",\"tick\":"+tick+",\"frame\":"+read(e,BL+4,1)+",\"owner\":"+read(e,BL+6,2)+",\"strength\":"+read(e,BL+5,1)+",\"flags64\":"+read(e,U+0x64,1)+",\"mask98\":"+read(e,U+0x98,1)+",\"hp\":"+read(e,U+0x3a,1)+",\"hull\":"+read(e,W+8,2)+",\"fx\":"+fx+",\"audio\":"+audio+"}");if(tick<3)run(e,0x420be0);}}finally{e.dispose();}}}}
}